    import sys
    sys.setrecursionlimit(200000)

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            size = 0
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(size)

    def is_lucky(num):
        s = str(num)
        return all(c in '47' for c in s)

    # Generate lucky numbers up to n
    lucky_numbers = []
    from collections import deque
    q = deque([4, 7])
    while q and q[0] <= n:
        num = q.popleft()
        lucky_numbers.append(num)
        if num * 10 + 4 <= n:
            q.append(num * 10 + 4)
        if num * 10 + 7 <= n:
            q.append(num * 10 + 7)

    # Check if any existing component is lucky
    if any(is_lucky(size) for size in component_sizes):
        return '0\n'

    # DP to find if a sum is achievable and minimum number of components needed
    dp = {}

    for size in component_sizes:
        updated = {}
        for target, cost in dp.items():
            new_target = target + size
            if new_target <= n:
                new_cost = cost + 1
                if new_target not in dp or new_cost < dp[new_target]:
                    updated[new_target] = new_cost
        for target in list(dp.keys()) + list(updated.keys()):
            dp[target] = dp.get(target, float('inf'))
            updated_cost = dp.get(target, float('inf'))
            if updated and target in updated:
                updated_cost = min(updated_cost, updated[target])
        dp |= updated

    # Find minimum components for any lucky number
    min_components = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp and dp[lucky] < min_components:
            min_components = dp[lucky]

    if min_components == float('inf'):
        return '-1\n'
    else:
        # Need (min_components - 1) roads to merge min_components components
        return f'{min_components - 1}\n'

