        nonlocal max_happy

        if idx == n_friends:
            max_happy = max(max_happy, selected_count)
            return

        # Pruning: even if all remaining non-conflicting friends can be added,
        # we can't beat max_happy
        if selected_count + (n_friends - idx) <= max_happy:
            return

        # Try including friend idx if no conflicts with already selected
        can_include = True
        for j in range(idx):
            if conflict[idx][j]:
                can_include = False
                break

        if can_include:
            dfs(idx + 1, selected_count + 1, conflict_mask | (1 << idx))

        # Try excluding friend idx
        dfs(idx + 1, selected_count, conflict_mask)

    dfs(0, 0, 0)

    return str(max_happy)

