        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                a, b = int(parts[0]), int(parts[1])
                start_diagonals.append((a, b))

    # Goal triangulation (n-3 diagonals after start)
    goal_diagonals = []
    for i in range(n - 2, len(lines)):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                a, b = int(parts[0]), int(parts[1])
                goal_diagonals.append((a, b))

    # Build adjacency for polygon triangulation analysis
    # For a regular n-gon, each triangulation has n-3 diagonals

    start_set = set()
    for di in start_diagonals:
        start_set.add(tuple(sorted(di)))

    goal_set = set()
    for di in goal_diagonals:
        goal_set.add(tuple(sorted(di)))

    # Find diagonals to flip (difference between start and goal)
    # Strategy: flip diagonals that need to change

    steps = []

    # For each diagonal in start that's not in goal
    for d in start_diagonals:
        if sorted(d) not in goal_set:
            steps.append(d)

    # For each diagonal in goal that's not in start
    for d in goal_diagonals:
        if sorted(d) not in start_set:
            steps.append(d)

    k = len(steps)
    result = str(k) + '\n' + '\n'.join(f"{a} {b}" for a, b in steps) + '\n'

