                if op == 'R':
                    # Shift right: column j gets value from column (j-2 mod n)+1
                    # Actually new[j] = matrix[i][prev] where prev is shifted
                    # After R: new[n-1] = old[0], new[0] = old[n-1], etc.
                    # element at col j goes to col (j+1) mod n
                    for i in range(n):
                        matrix[i] = [matrix[i][(j - 1) % n] for j in range(n)]

                elif op == 'L':
                    # Shift left: element at col j goes to col (j-1) mod n
                    for i in range(n):
                        matrix[i] = [matrix[i][(j + 1) % n] for j in range(n)]

                elif op == 'D':
                    # Shift down: row i gets from row (i-1) mod n
                    for j in range(n):
                        col = [matrix[i][j] for i in range(n)]
                        for i in range(n):
                            matrix[i][j] = col[(i - 1) % n]

                elif op == 'U':
                    # Shift up: row i gets from row (i+1) mod n
                    for j in range(n):
                        col = [matrix[i][j] for i in range(n)]
                        for i in range(n):
                            matrix[i][j] = col[(i + 1) % n]

                elif op == 'I':
                    # Inverse each row
                    for i in range(n):
                        # row[i][j] is the value at position j in row i
                        # inverse: position v should contain old_pos where old_val = v
                        pos_to_val = matrix[i]  # pos_to_val[j] = value at position j
                        val_to_pos = [0] * n
                        for p in range(n):
                            val_to_pos[pos_to_val[p] - 1] = p + 1  # 1-indexed
                        for j in range(n):
