                        # Inverse: if col_vals[v-1] = p, then new position p should have value v
                        pos_to_val = col_vals  # pos_to_val[p] = value at position p
                        val_to_pos = [0] * n
                        for p in range(n):
                            val_to_pos[pos_to_val[p] - 1] = p + 1  # 1-indexed
                        # Write back
                        for i in range(n):
                            matrix[i][j] = val_to_pos[i]

        # Build output
