    tokens = input_str.strip().split()
    if not tokens:
        return ""

    iterator = iter(tokens)
    try:
        q_str = next(iterator, None)
        if q_str is None:
            return ""
        q = int(q_str)

        results = []

        for _ in range(q):
            n_str = next(iterator, None)
            if n_str is None:
                break
            n = int(n_str)

            arr = []
            for _ in range(n):
                val_str = next(iterator, None)
                if val_str is None:
                    break
                arr.append(int(val_str))

            # Find distinct values and sort them
            distinct_vals = sorted(set(arr))

            # Track min and max positions for each value
            min_pos = {}
            max_pos = {}
            for i, val in enumerate(arr):
                if val not in min_pos:
                    min_pos[val] = i
                    max_pos[val] = i
                else:
                    max_pos[val] = i

            # Find the longest contiguous subsegment of distinct values
            # where each consecutive pair (u[i], u[i+1]) satisfies max_pos[u[i]] < min_pos[u[i+1]]
            longest = 1
            current = 1

            for i in range(len(distinct_vals) - 1):
                prev_val = distinct_vals[i]
                curr_val = distinct_vals[i+1]

                if max_pos[prev_val] < min_pos[curr_val]:
                    current += 1
                else:
                    current = 1

                longest = max(longest, current)

            # Result is distinct values count minus longest valid subsegment length
            results.append(str(len(distinct_vals) - longest))

        return '\n'.join(results)
    except (StopIteration, ValueError):
        return ""

