def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])
    d1, d2 = int(lines[1]), int(lines[2])

    A = []
    B = []
    for i in range(3, 3 + N):
        parts = lines[i].split()
        A.append((float(parts[0]), float(parts[1])))
        B.append((float(parts[2]), float(parts[3])))

    def dist(t):
        return math.hypot(A[t][0] - B[t][0], A[t][1] - B[t][1])

    has_said_hell = False
    dist_was_away = False

    count = 0

    for t in range(N):
        d = dist(t)
        is_near = d <= d1

        if t == 0:
            if is_near:
                count += 1
            has_said_hell = True
        else:
            if is_near and not dist_was_away:
                # Currently near but previous was also near
                pass
            elif is_near and dist_was_away:
                # Came close after being away
                count += 1
            else:
                # We were close before, stayed away now
                pass

        dist_was_away = d > d2 + 0.00001

    return str(count)

