def quadratic_solve(A, B, C, low, high):
    """Solve A*t^2 + B*t + C <= 0 for t in [low, high]"""
    if abs(A) < 1e-12:
        return None

    if A > 0:
        # Parabola opens up: solution between roots
        D = B**2 - 4 * A * C
        if D < 0:
            return None
        disc_sqrt = math.sqrt(D)
        t1 = (-B - disc_sqrt) / (2 * A)
        t2 = (-B + disc_sqrt) / (2 * A)
        # We want t in [t1, t2]
        start_t = max(t_arr, low)
        end_t = min(t_dep, high)
        if t1 <= t2:
            overlap_start = max(low, t1)
            overlap_end = min(high, t2)
            if overlap_start <= overlap_end:
                return overlap_start
        return None
    else:
        # A < 0: parabola opens down, solution outside roots
        D = B**2 - 4 * A * C
        if D < 0:
            return None
        disc_sqrt = math.sqrt(D)
        t1 = (-B - disc_sqrt) / (2 * A)
        t2 = (-B + disc_sqrt) / (2 * A)
        if t1 <= t2:
            t1, t2 = t2, t1
        overlap_start = max(low, t1)
        overlap_end = min(high, t2)
        if overlap_start <= overlap_end:
            return overlap_start
        return None

