    # Special case: 2x3 or 3x2 can only use 4 cells out of 6
    if (n == 2 and m == 3) or (n == 3 and m == 2):
        return "4\n"

    # General case: all cells can be matched if even, all but 1 if odd
    return f"{s - s % 2}\n"

