import collections

def solve_segment(n, w, x, k):
    """Find minimum cuts for given k.

    A scene is valid if all photos in it can share exactly k flowers.
    This requires max(x[l..r]) - min(x[l..r]) <= w - k for the segment.
    """
    if n <= 1:
        return 0
    if w - k >= max(x) - min(x):
        return 0

    left = 0
    q_min = collections.deque()
    q_max = collections.deque()
    max_len = 1

    for right in range(n):
        while q_min and x[x[q_min[-1]]] >= x[x[right]]:
            q_min.pop()
        q_min.append(right)

        while q_max and x[x[q_max[-1]]] <= x[x[right]]:
            q_max.pop()
        q_max.append(right)

        while x[x[q_max[0]]] - x[x[q_min[0]]] > w - k:
            left += 1
            while q_min and q_min[0] < left:
                q_min.popleft()
            while q_max and q_max[0] < left:
                q_max.popleft()

        max_len = max(max_len, right - left + 1)

    return (n + max_len - 1) // max_len - 1

