        end += 1
    num = int(s[pos:end])
    return num, end

def parse_expr(s, pos):
    left, pos = parse_term(s, pos)

    while pos < len(s) and s[pos] == '+':
        pos += 1
        right, pos = parse_term(s, pos)
        left = add_terms(left, right)

    return CustomEq(str(left)), pos

def parse_term(s, pos):
    if s[pos] == '(':
        expr, pos = parse_expr(s, pos + 1)
        if pos < len(s) and s[pos] == ')':
            pos += 1
            num, pos_end = parse_number(s, pos)
            return repeat_term(num, expr), pos_end
        else:
            raise ValueError("Missing closing parenthesis")
    else:
        num, pos = parse_number(s, pos)

        if pos < len(s) and s[pos] == '-':
            pos += 1
            num2, pos_end = parse_number(s, pos)
            if num <= num2:
                return range_concat(num, num2), pos_end
            else:
                raise ValueError(f"Invalid range: {num}-{num2}")
        else:
            return CustomEq(str(num)), pos

def add_terms(left, right):
    len_right = calc_digits(right)
    return CustomEq(str(left) + str(right))

def repeat_term(n, expr):
    s = str(expr)
    n_str = s * n
    result = 0
    mod = 10**9 + 7
    for c in n_str:
        result = (result * 10 + int(c)) % mod
    return CustomEq(str(result))

def range_concat(l, r):
    s = ''
    for i in range(l, r + 1):
        s += str(i)
    return CustomEq(s)

def calc_digits(expr):
    return len(str(expr))

def main_solve(s: str):
    MOD = 10**9 + 7
    pos = 0
    left, pos = parse_term(s, pos)

    while pos < len(s) and s[pos] == '+':
        pos += 1
        right, pos = parse_term(s, pos)
        left = add_terms(left, right)

    return str(left) % MOD

def solution(input_str: str):
    return main_solve(input_str.strip())

