def solution(s):
    # Parse input - handle both line-based and space-separated formats
    s = s.strip()
    lines = s.split('\n')

    # First line: n
    n_line = lines[0].strip()
    n = int(n_line) if n_line else 0

    # Second line: ai values - they might be on same line or spread
    ai_values = []
    for line in lines[1:]:
        for token in line.split():
            ai_values.append(int(token))

    a = ai_values[:n]  # Take exactly n values

    def solve(T):
        """Simulate for starting position T, return time when trapped or -1"""
        left = set()
        right = set()

        for t in range(1, 2000000):
            # Krakozyabra position: starts at T, moves right 1 per second
            pos = T + t

            # Track newfalls by icicle position
            new_fallen = set()
            for i in range(1, n + 1):
                # Icicle i falls at time |i - T| + a[i-1]
                fall_time = abs(i - T) + a[i - 1]
                if t >= fall_time:
                    if i not in left and i not in right:
                        if i < pos:
                            new_fallen.add(i)
                        else:
                            new_fallen.add(i)

            for i in new_fallen:
                if i < pos:
                    left.add(i)
                else:
                    right.add(i)

            # Krakozyabra trapped if fallen icicles on BOTH sides
            if left and right:
                return t

        return -1

    best = float('inf')

    # Try all possible launch positions T
    for T in range(1, n + 1):
        t = solve(T)
        if t != -1:
            best = min(best, t)

    if best == float('inf'):
        return "-1\n"

    return f"{best}\n"

