def solution(input_str):
    if isinstance(input_str, str):
        lines = input_str.strip().split('\n')
    else:
        lines = input_str.strip().split('\n')

    t = int(lines[0])
    output = []

    idx = 1
    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1
        a = lines[idx]
        idx += 1
        b = lines[idx]
        idx += 1

        if n != len(a) or n != len(b):
            output.append("-1")
            continue

        # Build dependency graph
        edges = defaultdict(set)

        for i in range(n):
            if a[i] != b[i]:
                u = ord(a[i]) - ord('a')
                v = ord(b[i]) - ord('a')
                edges[u].add(v)

        # Find connected components
        all_chars = set(edges.keys())
        for targets in edges.values():
            all_chars.update(targets)

        # Union-Find
        parent = list(range(20))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        for u in edges:
            for v in edges[u]:
                union(u, v)

        # Count moves per component
        ans = 0
        processed = set()

        for u in edges:
            root = find(u)
            if root in processed:
                continue

            visited = defaultdict(set)
            q = [u]
            while q:
                curr = q.pop()
                for target in edges[curr]:
                    if target not in visited[curr]:
                        q.append(target)
                    if target not in visited[target]:
                        visited[target].add(find(curr))
                        if find(target) not in visited:
                            visited[find(target)].add(curr)

            # Simple heuristic: count unique target patterns
            targets = set()
            for src in edges:
                if find(src) == root:
                    targets.update(edges[src])

            if targets:
                ans += max(1, len(targets) if find(targets.pop()) != root else len(targets) - 1)
            processed.add(root)

        # If no changes needed
        if not edges:
            ans = 0

        output.append(str(ans))

    return '\n'.join(output)

import sys

MOD = 10**9 + 7
MAX_N = 10**6 + 1
MAX_R = 10**6 + 1
MAX_EXP = 20

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    q = int(lines[0])

    # Precompute smallest prime factor (SPF) for factorization
    spf = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N, i):
                if spf[j] == j:
                    spf[j] = i

    # Parse queries
    queries = []
    for i in range(1, q + 1):
        r, n = map(int, lines[i].split())
        queries.append((r, n))

    # Precompute g[r][a] where g[r][a] = fr(p^a) for any prime p
    # The recurrence is: fr+1(n) = sum_{d|n} fr(d)
    # Since fr(n) is multiplicative:
    # - f0(p^a) = 2 for a >= 1, f0(1) = 1
    # - g[r][a] = sum_{k=0}^a g[r-1][k]
    g = [[0] * MAX_EXP for _ in range(MAX_R)]
    g[0][0] = 1
    for a in range(1, MAX_EXP):
        g[0][a] = 2  # f0(p^a) = 2 for a >= 1

    for r in range(1, MAX_R):
        g[r][0] = 1  # fr(1) = 1
        for a in range(1, MAX_EXP):
            g[r][a] = (g[r][a-1] + g[r-1][a]) % MOD

    # Process queries
    results = []
    for r, n in queries:
        if n == 1:
            results.append('1')
        else:
            result = 1
            temp = n
            while temp > 1:
                p = spf[temp]
                a = 0
                while temp % p == 0:
                    temp //= p
                    a += 1
                result = (result * g[r][a]) % MOD
            results.append(str(result))

    return '\n'.join(results)
